<?php
declare(strict_types=1);
// Page: ?page=table — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 require_perm('view_tables'); $schema=current_schema(); $table=$_GET['table']??''; if(!table_exists($schema,$table)) throw new RuntimeException('Table not found'); $pageNo=max(1,(int)($_GET['p']??1)); $perPage=resolve_page_size($_GET); $cols=columns($schema,$table); $filters=parse_table_filters($_GET); $guard=large_table_guard($schema,$table,$filters); if($guard && $guard['level']==='block'){ $data=['rows'=>[],'total'=>0]; } else { $data=list_records($schema,$table,$filters,$pageNo,$perPage); $data['rows']=array_map('redact_row',$data['rows']); } $exportQs=$_GET; $exportQs['page']='export'; layout_start('Table: '.$table); ?><?php if($guard):?><div class="alert alert-<?=$guard['level']==='block'?'warning':'info'?>"><?=e($guard['message'])?></div><?php endif;?><div class="cardx"><div class="d-flex flex-wrap gap-2 justify-content-between"><div><h3><?=e($table)?></h3><p class="text-muted mb-0"><?=number_format($data['total'])?> matching records in <?=e($schema)?></p></div><div class="d-flex gap-2"><a class="btn btn-success" href="?page=form&mode=add&table=<?=urlencode($table)?>"><i class="fa fa-plus"></i> Add</a><a class="btn btn-outline-primary" href="?<?=http_build_query($exportQs)?>">Export CSV<?=$filters?' (filtered)':''?></a><a class="btn btn-outline-dark" href="?page=sync&table=<?=urlencode($table)?>">Copy/Sync</a></div></div><form class="search-panel mt-3" method="get"><input type="hidden" name="page" value="table"><input type="hidden" name="table" value="<?=e($table)?>"><div id="filters"><?php $show=$filters ?: [['col'=>'','op'=>'contains','val'=>'']]; foreach($show as $f):?><div class="filter-row"><select name="fcol[]" class="form-select"><option value="">Select column</option><?php foreach($cols as $c):?><option value="<?=e($c['name'])?>" <?=$f['col']===$c['name']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="fop[]" class="form-select"><option value="contains" <?=$f['op']==='contains'?'selected':''?>>contains</option><option value="equals" <?=$f['op']==='equals'?'selected':''?>>equals</option><option value="starts" <?=$f['op']==='starts'?'selected':''?>>starts with</option><option value="ends" <?=$f['op']==='ends'?'selected':''?>>ends with</option><option value="gt" <?=$f['op']==='gt'?'selected':''?>>&gt;</option><option value="lt" <?=$f['op']==='lt'?'selected':''?>>&lt;</option></select><input name="fval[]" class="form-control" value="<?=e($f['val'])?>" placeholder="Search value"></div><?php endforeach;?></div><template id="filter-template"><div class="filter-row"><select name="fcol[]" class="form-select"><option value="">Select column</option><?php foreach($cols as $c):?><option value="<?=e($c['name'])?>"><?=e($c['name'])?></option><?php endforeach;?></select><select name="fop[]" class="form-select"><option value="contains">contains</option><option value="equals">equals</option><option value="starts">starts with</option><option value="ends">ends with</option><option value="gt">&gt;</option><option value="lt">&lt;</option></select><input name="fval[]" class="form-control" placeholder="Search value"></div></template><div class="d-flex gap-2 mt-2 align-items-center"><button class="btn btn-primary">Search</button><button type="button" id="add-filter-btn" class="btn btn-outline-primary">Add Filter</button><a href="?page=table&table=<?=urlencode($table)?>" class="btn btn-outline-secondary">Reset</a><label class="ms-auto mb-0 small text-muted">Per page</label><select class="form-select form-select-sm w-auto" name="per_page" data-autosubmit><?php foreach(PAGE_SIZE_OPTIONS as $ps):?><option value="<?=$ps?>" <?=$perPage===$ps?'selected':''?>><?=$ps?></option><?php endforeach;?></select></div></form></div><div class="cardx table-card mt-3"><div class="table-scroll"><table class="table table-hover table-sm align-middle"><thead><tr><?php foreach($cols as $c):?><th><?=e($c['name'])?></th><?php endforeach;?><th class="sticky-actions">Actions</th></tr></thead><tbody><?php foreach($data['rows'] as $r): $key=row_key_query($schema,$table,$r);?><tr><?php foreach($cols as $c): $v=$r[$c['name']]??'';?><td title="<?=e($v)?>"><?=e(mb_strimwidth((string)$v,0,80,'...'))?></td><?php endforeach;?><td class="sticky-actions"><div class="btn-group btn-group-sm"><a class="btn btn-outline-primary" href="?page=view&table=<?=urlencode($table)?>&<?=$key?>">View</a><?php if(can('edit_records')):?><a class="btn btn-outline-warning" href="?page=form&mode=edit&table=<?=urlencode($table)?>&<?=$key?>">Edit</a><?php endif;?><?php if(can('duplicate_records')):?><a class="btn btn-outline-success" href="?page=form&mode=duplicate&table=<?=urlencode($table)?>&<?=$key?>">Duplicate</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php $pages=max(1,ceil($data['total']/$perPage));?><div class="p-3 d-flex justify-content-between"><span>Page <?=$pageNo?> of <?=$pages?></span><div><?php if($pageNo>1):?><a class="btn btn-sm btn-outline-primary" href="?<?=e(http_build_query(array_merge($_GET,['p'=>$pageNo-1])))?>">Prev</a><?php endif;?><?php if($pageNo<$pages):?><a class="btn btn-sm btn-outline-primary" href="?<?=http_build_query(array_merge($_GET,['p'=>$pageNo+1]))?>">Next</a><?php endif;?></div></div></div><?php layout_end(); exit;
